using System; using Newtonsoft.Json; using Newtonsoft.Json.Linq; using ChooGuard.Seeded; public static class BitsProbe { public static void Main(){double x=BitConverter.Int64BitsToDouble(unchecked((long)0x3fe278e93a3bfa76UL));double z=BitConverter.Int64BitsToDouble(unchecked((long)0x8000000000000000UL));var h=new JObject{["x"]=x,["z"]=z};var enc=LocalTapeCodec.Encode(h);var d=LocalTapeCodec.Parse(enc.ToString(Formatting.None));Console.WriteLine("input="+BitConverter.DoubleToInt64Bits(x).ToString("x16")+","+BitConverter.DoubleToInt64Bits(z).ToString("x16"));Console.WriteLine("token="+BitConverter.DoubleToInt64Bits((double)h["x"]).ToString("x16")+","+BitConverter.DoubleToInt64Bits((double)h["z"]).ToString("x16"));Console.WriteLine("rawtoken="+BitConverter.DoubleToInt64Bits((double)((JValue)h["z"]).Value).ToString("x16"));Console.WriteLine("rawoutput="+BitConverter.DoubleToInt64Bits((double)((JValue)d["z"]).Value).ToString("x16"));Console.WriteLine("output="+BitConverter.DoubleToInt64Bits((double)d["x"]).ToString("x16")+","+BitConverter.DoubleToInt64Bits((double)d["z"]).ToString("x16"));Console.WriteLine(enc.ToString(Formatting.None));}}